import{_ as r,o as t,c as l,a3 as o}from"./chunks/framework.BrO6lPIi.js";const u=JSON.parse('{"title":"MCP 工具集成","description":"本文件系统性梳理 AI Helper 的 MCP（Model Context Protocol）工具集成方案，覆盖客户端实现、远程工具发现、协议适配、错误处理、服务分组与开关控制、deny-list 模型、缓存同步与竞态处理、用户界面展示与安全控制等关键主题。","frontmatter":{"title":"MCP 工具集成","description":"本文件系统性梳理 AI Helper 的 MCP（Model Context Protocol）工具集成方案，覆盖客户端实现、远程工具发现、协议适配、错误处理、服务分组与开关控制、deny-list 模型、缓存同步与竞态处理、用户界面展示与安全控制等关键主题。"},"headers":[],"relativePath":"Chrome-扩展核心/Side-Panel-界面架构/工具面板集成/MCP-工具集成/index.md","filePath":"Chrome-扩展核心/Side-Panel-界面架构/工具面板集成/MCP-工具集成/index.md","lastUpdated":null}'),a={name:"Chrome-扩展核心/Side-Panel-界面架构/工具面板集成/MCP-工具集成/index.md"};function i(n,e,s,c,g,p){return t(),l("div",null,[...e[0]||(e[0]=[o(`<h1 id="mcp-工具集成" tabindex="-1">MCP 工具集成 <a class="header-anchor" href="#mcp-工具集成" aria-label="Permalink to &quot;MCP 工具集成&quot;">​</a></h1><details class="details custom-block"><summary>本文引用的源码文件</summary><p><strong>本文引用的文件</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/mcp/client.js" target="_blank" rel="noreferrer">agent/src/mcp/client.js</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/mcp/mcp-config.js" target="_blank" rel="noreferrer">agent/src/mcp/mcp-config.js</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/mcp/registry.js" target="_blank" rel="noreferrer">agent/src/mcp/registry.js</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js" target="_blank" rel="noreferrer">agent/src/server.js</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/tool-executor.js" target="_blank" rel="noreferrer">src/background/tool-executor.js</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/side_panel/tool-panel.js" target="_blank" rel="noreferrer">src/side_panel/tool-panel.js</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/side_panel/skill-selector.js" target="_blank" rel="noreferrer">src/side_panel/skill-selector.js</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/side_panel/agent-manager.js" target="_blank" rel="noreferrer">src/side_panel/agent-manager.js</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/options/toolbox-mcp.js" target="_blank" rel="noreferrer">src/options/toolbox-mcp.js</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/options/toolbox-config.js" target="_blank" rel="noreferrer">src/options/toolbox-config.js</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/shared/locales/en.js" target="_blank" rel="noreferrer">src/shared/locales/en.js</a></li></ul></details><h2 id="目录" tabindex="-1">目录 <a class="header-anchor" href="#目录" aria-label="Permalink to &quot;目录&quot;">​</a></h2><ol><li><a href="#引言">引言</a></li><li><a href="#项目结构">项目结构</a></li><li><a href="#核心组件">核心组件</a></li><li><a href="#架构总览">架构总览</a></li><li><a href="#详细组件分析">详细组件分析</a></li><li><a href="#依赖关系分析">依赖关系分析</a></li><li><a href="#性能与并发特性">性能与并发特性</a></li><li><a href="#故障排查指南">故障排查指南</a></li><li><a href="#结论">结论</a></li><li><a href="#附录配置与调用示例路径">附录：配置与调用示例路径</a></li></ol><h2 id="引言" tabindex="-1">引言 <a class="header-anchor" href="#引言" aria-label="Permalink to &quot;引言&quot;">​</a></h2><p>本文件系统性梳理 AI Helper 的 MCP（Model Context Protocol）工具集成方案，覆盖客户端实现、远程工具发现、协议适配、错误处理、服务分组与开关控制、deny-list 模型、缓存同步与竞态处理、用户界面展示与安全控制等关键主题。文档面向开发者与高级用户，既提供高层架构图，也给出代码级流程与关键路径引用，便于定位与二次扩展。</p><h2 id="项目结构" tabindex="-1">项目结构 <a class="header-anchor" href="#项目结构" aria-label="Permalink to &quot;项目结构&quot;">​</a></h2><p>本项目采用双进程架构：Chrome 扩展端（Manifest V3，位于 src/）与独立本地代理端 Agent（Node.js，位于 agent/）。MCP 能力由 Agent 端负责连接外部 MCP Server，并通过 HTTP API 暴露给扩展端；扩展端在 Background 中动态注册 MCP 工具，并在侧边栏与选项页提供管理与展示能力。</p><pre class="mermaid">graph TB
subgraph &quot;扩展端Chrome 扩展&quot;
BG[&quot;Background&lt;br/&gt;tool-executor.js&quot;]
SP[&quot;Side Panel&lt;br/&gt;tool-panel.js / skill-selector.js / agent-manager.js&quot;]
OPT[&quot;Options 页面&lt;br/&gt;toolbox-mcp.js / toolbox-config.js&quot;]
end
subgraph &quot;Agent 端Node.js&quot;
SRV[&quot;HTTP 路由&lt;br/&gt;server.js&quot;]
REG[&quot;注册表&lt;br/&gt;registry.js&quot;]
CFG[&quot;配置管理&lt;br/&gt;mcp-config.js&quot;]
CLI[&quot;MCP 客户端&lt;br/&gt;client.js&quot;]
end
EXT[&quot;外部 MCP Server&quot;]
OPT --&gt; SRV
SP --&gt; BG
BG --&gt; SRV
SRV --&gt; REG
REG --&gt; CLI
CLI --&gt; EXT
</pre><p><strong>图表来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/tool-executor.js#L547-L651" target="_blank" rel="noreferrer">src/background/tool-executor.js#L547-L651</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L1867-L1923" target="_blank" rel="noreferrer">agent/src/server.js#L1867-L1923</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/mcp/registry.js#L1-L55" target="_blank" rel="noreferrer">agent/src/mcp/registry.js#L1-L55</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/mcp/client.js#L35-L127" target="_blank" rel="noreferrer">agent/src/mcp/client.js#L35-L127</a></li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/tool-executor.js#L547-L651" target="_blank" rel="noreferrer">src/background/tool-executor.js#L547-L651</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L1867-L1923" target="_blank" rel="noreferrer">agent/src/server.js#L1867-L1923</a></li></ul><h2 id="核心组件" tabindex="-1">核心组件 <a class="header-anchor" href="#核心组件" aria-label="Permalink to &quot;核心组件&quot;">​</a></h2><ul><li>Agent 端 MCP 客户端：封装多种传输层（stdio/SSE/streamableHttp/websocket），统一 connect/listTools/callTool/disconnect 生命周期。</li><li>Agent 端 MCP 注册表：维护已连接 Client 实例，提供工具扁平化查询、按 serverId 过滤、工具调用、连接/断开、启停状态查询。</li><li>Agent 端 MCP 配置：持久化 mcp_servers.json，支持增删改查、启用/禁用、写锁保护与内存缓存。</li><li>扩展端 Background 工具注入：拉取 MCP 工具列表，构建 RAW_TOOLS/BUILTIN_TOOLS/TOOL_HANDLERS，并写入 chrome.storage.local.mcpTools。</li><li>扩展端 Side Panel 工具面板：从 storage 读取缓存，监听变更实时刷新，渲染服务分组、展开收起、工具详情与状态指示器。</li><li>扩展端 Options 页面：MCP 服务器增删改查、连接/断开、启用/禁用、环境变量与请求头编辑。</li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/mcp/client.js#L35-L184" target="_blank" rel="noreferrer">agent/src/mcp/client.js#L35-L184</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/mcp/registry.js#L1-L181" target="_blank" rel="noreferrer">agent/src/mcp/registry.js#L1-L181</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/mcp/mcp-config.js#L1-L129" target="_blank" rel="noreferrer">agent/src/mcp/mcp-config.js#L1-L129</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/tool-executor.js#L547-L739" target="_blank" rel="noreferrer">src/background/tool-executor.js#L547-L739</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/side_panel/tool-panel.js#L45-L239" target="_blank" rel="noreferrer">src/side_panel/tool-panel.js#L45-L239</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/options/toolbox-mcp.js#L1-L601" target="_blank" rel="noreferrer">src/options/toolbox-mcp.js#L1-L601</a></li></ul><h2 id="架构总览" tabindex="-1">架构总览 <a class="header-anchor" href="#架构总览" aria-label="Permalink to &quot;架构总览&quot;">​</a></h2><p>MCP 工具链路的端到端流程如下：用户在 Options 页面配置 MCP 服务器 → Agent 端通过 HTTP API 持久化配置并建立连接 → Registry 维护 Client 实例并暴露工具列表 → Background 拉取工具并动态注册为内置工具 → Side Panel 从 storage 读取缓存并渲染分组 UI。</p><pre class="mermaid">sequenceDiagram
participant User as &quot;用户&quot;
participant Options as &quot;Options 页面&lt;br/&gt;toolbox-mcp.js&quot;
participant Server as &quot;Agent HTTP 路由&lt;br/&gt;server.js&quot;
participant Registry as &quot;MCP 注册表&lt;br/&gt;registry.js&quot;
participant Client as &quot;MCP 客户端&lt;br/&gt;client.js&quot;
participant ExtBG as &quot;Background&lt;br/&gt;tool-executor.js&quot;
participant Storage as &quot;chrome.storage.local&quot;
participant SidePanel as &quot;Side Panel&lt;br/&gt;tool-panel.js&quot;
User-&gt;&gt;Options : 添加/编辑/连接 MCP 服务器
Options-&gt;&gt;Server : POST /api/mcp/servers / connect / toggle
Server-&gt;&gt;Registry : add/connect/toggle
Registry-&gt;&gt;Client : connect()
Client--&gt;&gt;Registry : {success, toolCount}
Registry--&gt;&gt;Server : {success, servers/tools}
Server--&gt;&gt;Options : 返回结果
ExtBG-&gt;&gt;Server : GET /api/mcp/tools + /servers
Server--&gt;&gt;ExtBG : tools[] + servers[]
ExtBG-&gt;&gt;Storage : set({mcpTools})
SidePanel-&gt;&gt;Storage : get(mcpTools) + onChanged
SidePanel--&gt;&gt;User : 渲染服务分组与工具详情
</pre><p><strong>图表来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/options/toolbox-mcp.js#L510-L560" target="_blank" rel="noreferrer">src/options/toolbox-mcp.js#L510-L560</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L1867-L1923" target="_blank" rel="noreferrer">agent/src/server.js#L1867-L1923</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/mcp/registry.js#L133-L167" target="_blank" rel="noreferrer">agent/src/mcp/registry.js#L133-L167</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/mcp/client.js#L96-L127" target="_blank" rel="noreferrer">agent/src/mcp/client.js#L96-L127</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/tool-executor.js#L547-L651" target="_blank" rel="noreferrer">src/background/tool-executor.js#L547-L651</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/side_panel/tool-panel.js#L81-L102" target="_blank" rel="noreferrer">src/side_panel/tool-panel.js#L81-L102</a></li></ul><h2 id="详细组件分析" tabindex="-1">详细组件分析 <a class="header-anchor" href="#详细组件分析" aria-label="Permalink to &quot;详细组件分析&quot;">​</a></h2><h3 id="agent-端-mcp-客户端-协议适配与错误处理" tabindex="-1">Agent 端 MCP 客户端（协议适配与错误处理） <a class="header-anchor" href="#agent-端-mcp-客户端-协议适配与错误处理" aria-label="Permalink to &quot;Agent 端 MCP 客户端（协议适配与错误处理）&quot;">​</a></h3><ul><li>传输适配：根据 transport 字段选择 stdio/sse/streamableHttp/websocket，校验必要参数（command/url），支持 headers/env/cwd/args。</li><li>连接流程：创建 Client，connect 后获取 serverInfo/capabilities，listTools 填充 tools，设置 connected=true。</li><li>工具调用：callTool 将 name/arguments 转发至远端，解析 content.text 拼接文本内容，统一返回 success/content/raw 或 error。</li><li>错误处理：连接失败时 disconnect 清理资源；调用失败时返回结构化错误信息；disconnect/close 均做 try/catch 保护。</li></ul><pre class="mermaid">classDiagram
class McpClient {
+string serverId
+string serverName
+object serverConfig
-object client
-object transport
+boolean connected
+array tools
+object serverInfo
+connect() Promise~object~
+callTool(toolName, args) Promise~object~
+disconnect() Promise~void~
+getStatus() object
-_createTransport() object
}
</pre><p><strong>图表来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/mcp/client.js#L35-L184" target="_blank" rel="noreferrer">agent/src/mcp/client.js#L35-L184</a></li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/mcp/client.js#L35-L184" target="_blank" rel="noreferrer">agent/src/mcp/client.js#L35-L184</a></li></ul><h3 id="agent-端-mcp-注册表-工具发现与调用" tabindex="-1">Agent 端 MCP 注册表（工具发现与调用） <a class="header-anchor" href="#agent-端-mcp-注册表-工具发现与调用" aria-label="Permalink to &quot;Agent 端 MCP 注册表（工具发现与调用）&quot;">​</a></h3><ul><li>初始化：启动时遍历 enabled 的服务器，逐个 connect，统计成功/失败数量并输出日志。</li><li>工具查询：getMcpTools 扁平化所有已连接 Client 的工具，支持按 serverId 过滤。</li><li>工具调用：callMcpTool 校验 serverId 存在且 connected，转发到对应 Client.callTool。</li><li>连接管理：connectMcpServer 先断开旧连接再新建；disconnectMcpServer 清理 Map 条目；shutdownMcpRegistry 关闭全部。</li></ul><pre class="mermaid">flowchart TD
Start([&quot;调用 callMcpTool(serverId, toolName, args)&quot;]) --&gt; Lookup[&quot;查找 clients.get(serverId)&quot;]
Lookup --&gt; Exists{&quot;是否存在？&quot;}
Exists --&gt; |否| Err1[&quot;返回 serverNotFound&quot;]
Exists --&gt; |是| Connected{&quot;是否已连接？&quot;}
Connected --&gt; |否| Err2[&quot;返回 serverNotConnected&quot;]
Connected --&gt; |是| Call[&quot;client.callTool(toolName, args)&quot;]
Call --&gt; Return[&quot;返回 {success, content/raw/error}&quot;]
</pre><p><strong>图表来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/mcp/registry.js#L116-L128" target="_blank" rel="noreferrer">agent/src/mcp/registry.js#L116-L128</a></li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/mcp/registry.js#L26-L55" target="_blank" rel="noreferrer">agent/src/mcp/registry.js#L26-L55</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/mcp/registry.js#L89-L108" target="_blank" rel="noreferrer">agent/src/mcp/registry.js#L89-L108</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/mcp/registry.js#L133-L167" target="_blank" rel="noreferrer">agent/src/mcp/registry.js#L133-L167</a></li></ul><h3 id="agent-端-mcp-配置-持久化与写锁" tabindex="-1">Agent 端 MCP 配置（持久化与写锁） <a class="header-anchor" href="#agent-端-mcp-配置-持久化与写锁" aria-label="Permalink to &quot;Agent 端 MCP 配置（持久化与写锁）&quot;">​</a></h3><ul><li>存储位置：~/.ai-helper-agent/mcp_servers.json。</li><li>读写策略：内存缓存 + mtime 失效；写操作使用 withWriteLock 串行化，避免并发写损坏。</li><li>功能接口：load/save/add/remove/toggle，统一返回 success 或带 i18n 的错误消息。</li></ul><pre class="mermaid">flowchart TD
A[&quot;addMcpServer(server)&quot;] --&gt; B[&quot;loadMcpConfig()&quot;]
B --&gt; C{&quot;id 已存在？&quot;}
C --&gt; |是| D[&quot;合并更新&quot;]
C --&gt; |否| E[&quot;push 新项&quot;]
D --&gt; F[&quot;saveMcpConfig(config)&quot;]
E --&gt; F
F --&gt; G[&quot;withWriteLock 串行写入 + 更新缓存&quot;]
</pre><p><strong>图表来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/mcp/mcp-config.js#L86-L98" target="_blank" rel="noreferrer">agent/src/mcp/mcp-config.js#L86-L98</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/mcp/mcp-config.js#L69-L80" target="_blank" rel="noreferrer">agent/src/mcp/mcp-config.js#L69-L80</a></li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/mcp/mcp-config.js#L1-L129" target="_blank" rel="noreferrer">agent/src/mcp/mcp-config.js#L1-L129</a></li></ul><h3 id="扩展端-background-工具注入与调度" tabindex="-1">扩展端 Background 工具注入与调度 <a class="header-anchor" href="#扩展端-background-工具注入与调度" aria-label="Permalink to &quot;扩展端 Background 工具注入与调度&quot;">​</a></h3><ul><li>全局开关：检查 mcpEnabled，未开启则跳过加载。</li><li>互斥加载：mcpLoadLock 保证多次 load/unload 串行执行，避免竞态。</li><li>并行拉取：Promise.all 同时获取 tools 与 servers，构建 disabledServerIds 集合。</li><li>动态注册：为每个工具生成 id=mcp_{serverId}_{name}，注入 RAW_TOOLS/BUILTIN_TOOLS/TOOL_HANDLERS，并记录元信息映射。</li><li>缓存同步：将过滤后的工具列表写入 chrome.storage.local.mcpTools，供 Side Panel 消费。</li><li>会话强制下发：sessionForcedMcpServers 保存“/”触发器指定的服务，绕过关闭/排除列表。</li></ul><pre class="mermaid">flowchart TD
S([&quot;loadMcpTools()&quot;]) --&gt; Lock[&quot;等待 mcpLoadLock&quot;]
Lock --&gt; CheckGlobal{&quot;mcpEnabled === true ?&quot;}
CheckGlobal --&gt; |否| End1[&quot;返回 0&quot;]
CheckGlobal --&gt; |是| Clean[&quot;unloadMcpToolsInternal()&quot;]
Clean --&gt; Fetch[&quot;Promise.all(getMcpTools(), getMcpServers())&quot;]
Fetch --&gt; Filter[&quot;过滤 disabledServerIds&quot;]
Filter --&gt; Register[&quot;注册 RAW_TOOLS/BUILTIN_TOOLS/HANDLERS&quot;]
Register --&gt; Cache[&quot;set(chrome.storage.local.mcpTools)&quot;]
Cache --&gt; Release[&quot;释放 mcpLoadLock&quot;]
</pre><p><strong>图表来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/tool-executor.js#L547-L651" target="_blank" rel="noreferrer">src/background/tool-executor.js#L547-L651</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/tool-executor.js#L653-L684" target="_blank" rel="noreferrer">src/background/tool-executor.js#L653-L684</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/tool-executor.js#L711-L739" target="_blank" rel="noreferrer">src/background/tool-executor.js#L711-L739</a></li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/tool-executor.js#L547-L739" target="_blank" rel="noreferrer">src/background/tool-executor.js#L547-L739</a></li></ul><h3 id="服务分组与-deny-list-模型" tabindex="-1">服务分组与 deny-list 模型 <a class="header-anchor" href="#服务分组与-deny-list-模型" aria-label="Permalink to &quot;服务分组与 deny-list 模型&quot;">​</a></h3><ul><li>分组维度：按 serverId 聚合工具，形成服务级行，显示 serverName、工具数、ID 与展开按钮。</li><li>三层判定： <ul><li>closed：用户在工具配置弹窗关闭的服务（agentMcpClosedServers_\${agentId}）。</li><li>excluded：助手编辑器排除的服务（agent.mcpExcludedServerIds）。</li><li>forced：/ 触发器手动指定的服务，强制下发并绕过前两者。</li></ul></li><li>生效规则：forced &gt; 非 closed/excluded；closed/excluded 为 deny-list，不在列表中即视为开放。</li></ul><pre class="mermaid">flowchart TD
T[&quot;工具过滤&quot;] --&gt; CheckMcp{&quot;是否为 MCP 工具？&quot;}
CheckMcp --&gt; |否| Keep[&quot;保留&quot;]
CheckMcp --&gt; |是| Global{&quot;mcpEnabled &amp;&amp; agentConnected &amp;&amp; registered ?&quot;}
Global --&gt; |否| Drop[&quot;丢弃&quot;]
Global --&gt; Forced{&quot;forcedMcpServerIds 包含？&quot;}
Forced --&gt; |是| Keep
Forced --&gt; |否| Closed{&quot;closed 包含？&quot;}
Closed --&gt; |是| Drop
Closed --&gt; |否| Excluded{&quot;excluded 包含？&quot;}
Excluded --&gt; |是| Drop
Excluded --&gt; |否| Keep
</pre><p><strong>图表来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/tool-executor.js#L1208-L1247" target="_blank" rel="noreferrer">src/background/tool-executor.js#L1208-L1247</a></li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/tool-executor.js#L1208-L1247" target="_blank" rel="noreferrer">src/background/tool-executor.js#L1208-L1247</a></li></ul><h3 id="扩展端-side-panel-工具展示与交互" tabindex="-1">扩展端 Side Panel 工具展示与交互 <a class="header-anchor" href="#扩展端-side-panel-工具展示与交互" aria-label="Permalink to &quot;扩展端 Side Panel 工具展示与交互&quot;">​</a></h3><ul><li>数据源：优先通过 runtime.sendMessage(&#39;GET_MCP_TOOLS&#39;) 直接从 Background 获取，否则回退到 chrome.storage.local.mcpTools。</li><li>实时更新：监听 storage.onChanged，当 mcpTools/mcpEnabled 变化时刷新分类计数、标题与工具栏状态点。</li><li>服务分组渲染：按 serverId 分组，计算 effectiveOpen（未被 closed 且未被 excluded），未开放的服务排在后面并附角标。</li><li>交互行为： <ul><li>服务行 checkbox：切换服务级开关（denied/open）。</li><li>展开按钮：展开只读工具列表（名称+描述）。</li><li>全选/取消全选：仅对当前可见且可操作的项生效。</li><li>计数与角标：按服务粒度统计 open/total，区分被助手排除的行不计入 open。</li></ul></li></ul><pre class="mermaid">sequenceDiagram
participant SP as &quot;Side Panel&quot;
participant BG as &quot;Background&quot;
participant Store as &quot;chrome.storage.local&quot;
SP-&gt;&gt;BG : sendMessage(&#39;GET_MCP_TOOLS&#39;)
BG--&gt;&gt;SP : {success, tools}
alt 获取失败
SP-&gt;&gt;Store : get([&#39;mcpTools&#39;])
Store--&gt;&gt;SP : mcpTools[]
end
SP-&gt;&gt;Store : onChanged 监听 mcpTools/mcpEnabled
SP--&gt;&gt;User : 渲染服务分组/工具详情/状态指示器
</pre><p><strong>图表来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/side_panel/tool-panel.js#L81-L102" target="_blank" rel="noreferrer">src/side_panel/tool-panel.js#L81-L102</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/side_panel/tool-panel.js#L148-L202" target="_blank" rel="noreferrer">src/side_panel/tool-panel.js#L148-L202</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/side_panel/skill-selector.js#L574-L599" target="_blank" rel="noreferrer">src/side_panel/skill-selector.js#L574-L599</a></li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/side_panel/tool-panel.js#L45-L239" target="_blank" rel="noreferrer">src/side_panel/tool-panel.js#L45-L239</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/side_panel/tool-panel.js#L560-L759" target="_blank" rel="noreferrer">src/side_panel/tool-panel.js#L560-L759</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/side_panel/skill-selector.js#L560-L759" target="_blank" rel="noreferrer">src/side_panel/skill-selector.js#L560-L759</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/side_panel/agent-manager.js#L920-L1000" target="_blank" rel="noreferrer">src/side_panel/agent-manager.js#L920-L1000</a></li></ul><h3 id="扩展端-options-页面-mcp-服务器管理" tabindex="-1">扩展端 Options 页面：MCP 服务器管理 <a class="header-anchor" href="#扩展端-options-页面-mcp-服务器管理" aria-label="Permalink to &quot;扩展端 Options 页面：MCP 服务器管理&quot;">​</a></h3><ul><li>列表渲染：显示连接状态、启用状态、transport、命令/URL、工具列表折叠区。</li><li>表单编辑：支持 stdio/SSE/streamableHttp/websocket 四种传输方式，按需显示 command/args/url，以及 env/headers 多行键值对。</li><li>操作接口：add/remove/connect/disconnect/toggle，统一通过 agentApi 调用后端路由。</li><li>搜索与筛选：支持按 name/id/command/url/args 模糊搜索，以及 enabled/disabled 状态筛选。</li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/options/toolbox-mcp.js#L1-L601" target="_blank" rel="noreferrer">src/options/toolbox-mcp.js#L1-L601</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/options/toolbox-config.js#L109-L142" target="_blank" rel="noreferrer">src/options/toolbox-config.js#L109-L142</a></li></ul><h3 id="agent-端-http-路由-api-契约" tabindex="-1">Agent 端 HTTP 路由（API 契约） <a class="header-anchor" href="#agent-端-http-路由-api-契约" aria-label="Permalink to &quot;Agent 端 HTTP 路由（API 契约）&quot;">​</a></h3><ul><li>服务器管理：POST /api/mcp/servers（新增）、DELETE /api/mcp/servers（删除）。</li><li>连接控制：POST /api/mcp/servers/connect、/disconnect、/toggle（enabled 切换时若禁用会先断开）。</li><li>工具调用：POST /api/mcp/call（serverId + toolName + args）。</li><li>审计日志：所有关键操作均调用 logSystem 记录 serverId、success 等上下文。</li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L1867-L1923" target="_blank" rel="noreferrer">agent/src/server.js#L1867-L1923</a></li></ul><h2 id="依赖关系分析" tabindex="-1">依赖关系分析 <a class="header-anchor" href="#依赖关系分析" aria-label="Permalink to &quot;依赖关系分析&quot;">​</a></h2><ul><li>Agent 端： <ul><li>registry.js 依赖 client.js（连接与调用）、mcp-config.js（配置读写）、i18n（多语言错误提示）。</li><li>server.js 作为 HTTP 入口，依赖 registry.js 提供的工具与连接能力。</li></ul></li><li>扩展端： <ul><li>background/tool-executor.js 依赖 AgentClient（HTTP 调用）、chrome.storage.local（缓存）、内部工具注册表。</li><li>side_panel/tool-panel.js 与 skill-selector.js 依赖 chrome.storage.local 与 runtime message 机制。</li><li>options/toolbox-mcp.js 依赖 toolbox-shared.agentApi 与 i18n。</li></ul></li></ul><pre class="mermaid">graph LR
REG[&quot;registry.js&quot;] --&gt; CLI[&quot;client.js&quot;]
REG --&gt; CFG[&quot;mcp-config.js&quot;]
SRV[&quot;server.js&quot;] --&gt; REG
BG[&quot;tool-executor.js&quot;] --&gt; SRV
SP[&quot;tool-panel.js&quot;] --&gt; BG
OPT[&quot;toolbox-mcp.js&quot;] --&gt; SRV
</pre><p><strong>图表来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/mcp/registry.js#L1-L5" target="_blank" rel="noreferrer">agent/src/mcp/registry.js#L1-L5</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L1867-L1923" target="_blank" rel="noreferrer">agent/src/server.js#L1867-L1923</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/tool-executor.js#L547-L651" target="_blank" rel="noreferrer">src/background/tool-executor.js#L547-L651</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/options/toolbox-mcp.js#L510-L560" target="_blank" rel="noreferrer">src/options/toolbox-mcp.js#L510-L560</a></li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/mcp/registry.js#L1-L181" target="_blank" rel="noreferrer">agent/src/mcp/registry.js#L1-L181</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L1867-L1923" target="_blank" rel="noreferrer">agent/src/server.js#L1867-L1923</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/tool-executor.js#L547-L739" target="_blank" rel="noreferrer">src/background/tool-executor.js#L547-L739</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/options/toolbox-mcp.js#L1-L601" target="_blank" rel="noreferrer">src/options/toolbox-mcp.js#L1-L601</a></li></ul><h2 id="性能与并发特性" tabindex="-1">性能与并发特性 <a class="header-anchor" href="#性能与并发特性" aria-label="Permalink to &quot;性能与并发特性&quot;">​</a></h2><ul><li>互斥锁： <ul><li>Background 侧 mcpLoadLock 串行化 load/unload，避免重复注册与缓存不一致。</li><li>Agent 侧 mcp-config.js 使用 withWriteLock 串行化写操作，防止并发写损坏配置文件。</li></ul></li><li>并行拉取：Background 侧 Promise.all 并行获取 tools 与 servers，减少首屏延迟。</li><li>缓存策略： <ul><li>Background 将工具列表写入 chrome.storage.local.mcpTools，Side Panel 优先走 runtime message 直取，失败再回退 storage。</li><li>Agent 侧 mcp-config.js 使用内存缓存 + mtime 失效，降低频繁 IO。</li></ul></li><li>工具定义压缩：description 与 inputSchema 经过压缩函数处理，减少发送给模型的负载。</li></ul><p>[本节为通用性能建议，不直接分析具体文件]</p><h2 id="故障排查指南" tabindex="-1">故障排查指南 <a class="header-anchor" href="#故障排查指南" aria-label="Permalink to &quot;故障排查指南&quot;">​</a></h2><ul><li>无法加载 MCP 工具： <ul><li>检查全局开关 mcpEnabled 是否为 true。</li><li>确认 Agent 已连接且支持 MCP。</li><li>查看 Background 日志：[Background] load MCP tool failed...</li></ul></li><li>工具未出现在侧边栏： <ul><li>确认该工具所属服务未被 disabledServerIds 过滤。</li><li>检查服务是否在 closed/excluded 列表中，或被助手排除。</li><li>验证 chrome.storage.local.mcpTools 是否已写入。</li></ul></li><li>连接失败： <ul><li>检查 transport 必填参数（stdio 需要 command，SSE/streamableHttp/websocket 需要 url）。</li><li>查看 Agent 端日志与 i18n 错误消息（如 mcp.sseRequiresUrl、mcp.stdioRequiresCommand）。</li></ul></li><li>工具调用失败： <ul><li>确认 serverId 存在且 connected。</li><li>检查 callTool 返回的 error.message，必要时重试或降级。</li></ul></li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/tool-executor.js#L547-L651" target="_blank" rel="noreferrer">src/background/tool-executor.js#L547-L651</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/mcp/client.js#L96-L127" target="_blank" rel="noreferrer">agent/src/mcp/client.js#L96-L127</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/mcp/registry.js#L116-L128" target="_blank" rel="noreferrer">agent/src/mcp/registry.js#L116-L128</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/shared/locales/en.js#L959-L985" target="_blank" rel="noreferrer">src/shared/locales/en.js#L959-L985</a></li></ul><h2 id="结论" tabindex="-1">结论 <a class="header-anchor" href="#结论" aria-label="Permalink to &quot;结论&quot;">​</a></h2><p>本方案以 Agent 端为核心，统一封装 MCP 协议客户端与注册表，通过 HTTP API 向扩展端暴露工具发现与调用能力；扩展端在 Background 动态注册工具并缓存，Side Panel 与 Options 提供直观的管理与展示界面。通过 deny-list 模型与三层判定（closed/excluded/forced），在保证安全可控的前提下，灵活支持服务级开关与会话级强制下发。整体设计兼顾可扩展性、可观测性与用户体验。</p><p>[本节为总结性内容，不直接分析具体文件]</p><h2 id="附录-配置与调用示例路径" tabindex="-1">附录：配置与调用示例路径 <a class="header-anchor" href="#附录-配置与调用示例路径" aria-label="Permalink to &quot;附录：配置与调用示例路径&quot;">​</a></h2><ul><li>配置 MCP 服务器连接（Options 页面）： <ul><li>新增/编辑/删除：<a href="https://github.com/xiweicheng/ai-helper/blob/main/src/options/toolbox-mcp.js#L510-L560" target="_blank" rel="noreferrer">src/options/toolbox-mcp.js#L510-L560</a></li><li>连接/断开/启用切换：<a href="https://github.com/xiweicheng/ai-helper/blob/main/src/options/toolbox-mcp.js#L538-L560" target="_blank" rel="noreferrer">src/options/toolbox-mcp.js#L538-L560</a></li><li>后端路由：<a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L1867-L1923" target="_blank" rel="noreferrer">agent/src/server.js#L1867-L1923</a></li></ul></li><li>处理工具调用响应与错误恢复（Background）： <ul><li>动态注册与处理器：<a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/tool-executor.js#L597-L623" target="_blank" rel="noreferrer">src/background/tool-executor.js#L597-L623</a></li><li>调用 Agent 并返回结果：<a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/tool-executor.js#L616-L619" target="_blank" rel="noreferrer">src/background/tool-executor.js#L616-L619</a></li></ul></li><li>服务分组与 deny-list 判定： <ul><li>过滤逻辑与 forced 强制下发：<a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/tool-executor.js#L1208-L1247" target="_blank" rel="noreferrer">src/background/tool-executor.js#L1208-L1247</a></li></ul></li><li>Side Panel 工具展示与交互： <ul><li>缓存加载与 onChanged 监听：<a href="https://github.com/xiweicheng/ai-helper/blob/main/src/side_panel/tool-panel.js#L81-L102" target="_blank" rel="noreferrer">src/side_panel/tool-panel.js#L81-L102</a>, <a href="https://github.com/xiweicheng/ai-helper/blob/main/src/side_panel/tool-panel.js#L148-L202" target="_blank" rel="noreferrer">src/side_panel/tool-panel.js#L148-L202</a></li><li>服务分组与展开收起：<a href="https://github.com/xiweicheng/ai-helper/blob/main/src/side_panel/tool-panel.js#L560-L759" target="_blank" rel="noreferrer">src/side_panel/tool-panel.js#L560-L759</a></li><li>服务列表排序与有效开放标记：<a href="https://github.com/xiweicheng/ai-helper/blob/main/src/side_panel/skill-selector.js#L574-L599" target="_blank" rel="noreferrer">src/side_panel/skill-selector.js#L574-L599</a></li></ul></li><li>Agent 端 MCP 客户端与注册表： <ul><li>客户端连接/调用/断开：<a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/mcp/client.js#L96-L184" target="_blank" rel="noreferrer">agent/src/mcp/client.js#L96-L184</a></li><li>注册表工具查询与调用：<a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/mcp/registry.js#L89-L128" target="_blank" rel="noreferrer">agent/src/mcp/registry.js#L89-L128</a></li><li>配置持久化与写锁：<a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/mcp/mcp-config.js#L69-L98" target="_blank" rel="noreferrer">agent/src/mcp/mcp-config.js#L69-L98</a></li></ul></li></ul>`,92)])])}const b=r(a,[["render",i]]);export{u as __pageData,b as default};
